CREATE MATERIALIZED VIEW public.mv_station_crowd AS
 SELECT station_code,
    sum(cnt) AS total_passengers
   FROM ( SELECT tickets.source AS station_code,
            sum(tickets.passenger_count) AS cnt
           FROM public.tickets
          GROUP BY tickets.source
        UNION ALL
         SELECT tickets.destination AS station_code,
            sum(tickets.passenger_count) AS cnt
           FROM public.tickets
          GROUP BY tickets.destination) sub
  GROUP BY station_code
  WITH NO DATA;


