CREATE MATERIALIZED VIEW public.mv_train_coach_crowd AS
 SELECT train_no,
    coach_type,
    sum(passenger_count) AS total_passengers
   FROM ( SELECT t.train_no,
            t.passenger_count,
                CASE
                    WHEN (upper(TRIM(BOTH FROM td.train_type)) = 'ORDINARY'::text) THEN 'Second Class (2S)'::text
                    WHEN (upper(TRIM(BOTH FROM td.train_type)) = 'SHATABDI'::text) THEN
                    CASE
                        WHEN ((abs(hashtext((t.id)::text)) % 10) < 8) THEN 'Chair Car (CC)'::text
                        ELSE 'Executive Chair Car (EC)'::text
                    END
                    WHEN (upper(TRIM(BOTH FROM td.train_type)) = 'RAJDHANI'::text) THEN
                    CASE
                        WHEN ((abs(hashtext((t.id)::text)) % 20) < 2) THEN 'First AC (1A)'::text
                        WHEN ((abs(hashtext((t.id)::text)) % 20) < 7) THEN 'Second AC (2A)'::text
                        ELSE 'Third AC (3A)'::text
                    END
                    WHEN (upper(TRIM(BOTH FROM td.train_type)) = 'SUPERFAST'::text) THEN
                    CASE
                        WHEN ((abs(hashtext((t.id)::text)) % 100) < 4) THEN 'First AC (1A)'::text
                        WHEN ((abs(hashtext((t.id)::text)) % 100) < 19) THEN 'Second AC (2A)'::text
                        WHEN ((abs(hashtext((t.id)::text)) % 100) < 44) THEN 'Third AC (3A)'::text
                        WHEN ((abs(hashtext((t.id)::text)) % 100) < 94) THEN 'Sleeper (SL)'::text
                        ELSE 'Second Class (2S)'::text
                    END
                    ELSE
                    CASE
                        WHEN ((abs(hashtext((t.id)::text)) % 100) < 4) THEN 'First AC (1A)'::text
                        WHEN ((abs(hashtext((t.id)::text)) % 100) < 16) THEN 'Second AC (2A)'::text
                        WHEN ((abs(hashtext((t.id)::text)) % 100) < 36) THEN 'Third AC (3A)'::text
                        WHEN ((abs(hashtext((t.id)::text)) % 100) < 88) THEN 'Sleeper (SL)'::text
                        WHEN ((abs(hashtext((t.id)::text)) % 100) < 96) THEN 'Chair Car (CC)'::text
                        ELSE 'Second Class (2S)'::text
                    END
                END AS coach_type
           FROM (public.tickets t
             JOIN public.train_details td ON (((td.train_no)::text = (t.train_no)::text)))) sub
  GROUP BY train_no, coach_type
  WITH NO DATA;


