CREATE VIEW public.v_train_schedule AS
 SELECT td.train_no,
    td.train_name,
    td.train_type,
    ts.stop_number,
    s.station_code,
    s.station_name,
    s.city,
    s.state,
    ts.arrival_time,
    ts.departure_time,
    ts.halt_minutes,
    ts.day_number
   FROM ((public.train_stops ts
     JOIN public.train_details td ON (((ts.train_no)::text = (td.train_no)::text)))
     JOIN public.stations s ON (((ts.station_code)::text = (s.station_code)::text)))
  ORDER BY td.train_no, ts.stop_number;


